# Let me debug the extract_shape function
lines = grid_text.strip().split('\n')
grid = [list(map(int, line.split())) for line in lines]

def extract_shape(grid, color):
    positions = [(r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] == color]
    if not positions:
        return None, None, None
    rows = [r for r, c in positions]
    cols = [c for r, c in positions]
    min_r, max_r = min(rows), max(rows)
    min_c, max_c = min(cols), max(cols)
    shape = [grid[r][min_c:max_c+1] for r in range(min_r, max_r + 1)]
    bbox = (min_r, min_c, max_r, max_c)
    return (shape, bbox, color)

# Extract all shapes
shapes = {}
for color in [1, 3, 4, 8]:
    shape, bbox, c = extract_shape(grid, color)
    if shape:
        shapes[c] = {'shape': shape, 'bbox': bbox, 'color': c}
        print(f"Color {c}: shape {len(shape)}x{len(shape[0])}, bbox {bbox}")
        print("  Pattern:")
        for row in shape:
            print(f"    {row}")
        print()

